134	@code {
135	    private List<Grant>? grants;
136	    private List<Customer> customers = new();
137	    private List<Role> scopedRoles = new();
138	    private List<ApplicationUser> scopedUsers = new();
139	    private string? message;
140	    private bool isError;
141	
142	    private GrantForm form = new();
143	
144	    public class GrantForm
145	    {
146	        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Pick a customer.")]
147	        public Guid? CustomerId { get; set; }
148	        public GrantEffect Effect { get; set; } = GrantEffect.Allow;
149	        [System.ComponentModel.DataAnnotations.Required]
150	        [System.ComponentModel.DataAnnotations.StringLength(200)]
151	        public string Permission { get; set; } = string.Empty;
152	        [System.ComponentModel.DataAnnotations.Required]
153	        [System.ComponentModel.DataAnnotations.StringLength(200)]
154	        public string Resource { get; set; } = "*";
155	        public GrantSubjectType SubjectType { get; set; } = GrantSubjectType.Role;
156	        public Guid? RoleId { get; set; }
157	        public string? UserId { get; set; }
158	    }
159	
160	    protected override Task OnInitializedAsync() => LoadAsync();
161	
162	    private async Task LoadAsync()
163	    {
164	        await using var db = await DbFactory.CreateDbContextAsync();
165	        customers = await db.Customers.OrderBy(c => c.Name).ToListAsync();
166	        grants = await db.Grants
167	            .Include(g => g.Customer)
168	            .Include(g => g.Role)
169	            .Include(g => g.User)
170	            .OrderByDescending(g => g.CreatedAt)
171	            .ToListAsync();
172	        await RefreshSubjectsAsync(db);
173	    }
174	
175	    private async Task OnCustomerChanged()
176	    {
177	        form.RoleId = null;
178	        form.UserId = null;
179	        await using var db = await DbFactory.CreateDbContextAsync();
180	        await RefreshSubjectsAsync(db);
181	    }
182	
183	    private void OnSubjectTypeChanged()
184	    {
185	        form.RoleId = null;
186	        form.UserId = null;
187	    }
188	
189	    private async Task RefreshSubjectsAsync(GatekeeperDbContext db)
190	    {
191	        if (form.CustomerId is null)
192	        {
193	            scopedRoles = new();
194	            scopedUsers = new();
195	            return;
196	        }
197	        scopedRoles = await db.Roles.Where(r => r.CustomerId == form.CustomerId).OrderBy(r => r.Name).ToListAsync();
198	        scopedUsers = await db.Users.Where(u => u.CustomerId == form.CustomerId).OrderBy(u => u.Email).ToListAsync();
199	    }
200	
201	    private async Task AddAsync()
202	    {
203	        isError = false;
204	        message = null;
205	
206	        if (form.SubjectType == GrantSubjectType.Role && form.RoleId is null)
207	        {
208	            isError = true; message = "Pick a role for the grant."; return;
209	        }
210	        if (form.SubjectType == GrantSubjectType.User && string.IsNullOrEmpty(form.UserId))
211	        {
212	            isError = true; message = "Pick a user for the grant."; return;
213	        }
214	
215	        var grant = new Grant
216	        {
217	            CustomerId = form.CustomerId!.Value,
218	            Effect = form.Effect,
219	            Permission = form.Permission.Trim(),
220	            Resource = string.IsNullOrWhiteSpace(form.Resource) ? "*" : form.Resource.Trim(),
221	            RoleId = form.SubjectType == GrantSubjectType.Role ? form.RoleId : null,
222	            UserId = form.SubjectType == GrantSubjectType.User ? form.UserId : null,
223	        };
224	
225	        await using var db = await DbFactory.CreateDbContextAsync();
226	        db.Grants.Add(grant);
227	        await db.SaveChangesAsync();
228	        await Audit.LogAsync("Created", "Grant", grant.Id.ToString(),
229	            $"{grant.Effect} '{grant.Permission}' on '{grant.Resource}' for {form.SubjectType.ToString().ToLower()}", grant.CustomerId);
230	
231	        message = "Grant added.";
232	        var keepCustomer = form.CustomerId;
233	        var keepType = form.SubjectType;
234	        form = new GrantForm { CustomerId = keepCustomer, SubjectType = keepType };
235	        await LoadAsync();
236	    }
237	
238	    private async Task DeleteAsync(Grant g)
239	    {
240	        await using var db = await DbFactory.CreateDbContextAsync();
241	        var existing = await db.Grants.FindAsync(g.Id);
242	        if (existing is not null)
243	        {
244	            db.Grants.Remove(existing);
245	            await db.SaveChangesAsync();
246	            await Audit.LogAsync("Deleted", "Grant", g.Id.ToString(),
247	                $"Removed {existing.Effect} '{existing.Permission}' on '{existing.Resource}'", existing.CustomerId);
248	            message = "Grant deleted.";
249	            isError = false;
250	        }
251	        await LoadAsync();
252	    }
253	}
