            e.Property(a => a.EntityType).HasMaxLength(100).IsRequired();
            e.Property(a => a.EntityId).HasMaxLength(256).IsRequired();
            e.Property(a => a.Summary).HasMaxLength(2000).IsRequired();
            e.HasIndex(a => a.Timestamp);
        });
    }
}

