BASE=http://127.0.0.1:5225
echo "===== 1) PUT /api/policy (the wire-contract example) ====="
curl -s -X PUT "$BASE/api/policy" -H "Content-Type: application/json" -d '{
  "roles": [
    { "name": "Editor", "parent": "Staff" },
    { "name": "Staff",  "parent": null }
  ],
  "assignments": [
    { "subject": "user-42", "role": "Editor" }
  ],
  "grants": [
    { "subject": "user-42", "action": "document:read",   "resource": "doc-7", "effect": "Allow" },
    { "subject": "Staff",   "action": "document:delete", "resource": "doc-9", "effect": "Deny"  }
  ]
}'
echo; echo
echo "===== 2) POST /api/decisions : user-42 / document:delete / doc-7 (no grant -> default Deny) ====="
curl -s -X POST "$BASE/api/decisions" -H "Content-Type: application/json" -d '{"subject":"user-42","action":"document:delete","resource":"doc-7"}'
echo; echo
echo "===== 3) POST /api/decisions : user-42 / document:read / doc-7 (direct Allow) ====="
curl -s -X POST "$BASE/api/decisions" -H "Content-Type: application/json" -d '{"subject":"user-42","action":"document:read","resource":"doc-7"}'
echo; echo
echo "===== 4) POST /api/decisions : user-42 / document:delete / doc-9 (inherited role Deny via Editor->Staff) ====="
curl -s -X POST "$BASE/api/decisions" -H "Content-Type: application/json" -d '{"subject":"user-42","action":"document:delete","resource":"doc-9"}'
echo

